// easeOutQuad in, easeInQuad out — or LINEAR both ways when the importer says Canva faded
// linearly (`fadeEase` 1: Tectonic's fades, Drift on video pages).
LayerAnimationType.FADE -> {
    val linear = animation.param(CanvaAnimationParams.FADE_EASE) == 1.0
    LayerAnimationVisualState(
        alphaMultiplier = when {
            entering && linear -> p
            entering -> canvaEaseOutQuad(p)
            linear -> 1f - u
            else -> 1f - canvaEaseInQuad(u)
        },
        glyphMotion = writingStyle
    )
}

