LayerAnimationType.WIPE -> {
    if (abs(vector.x) > 0f) {
        LayerAnimationVisualState(
            scaleXMultiplier = progress.coerceAtLeast(0.001f),
            translationX = if (vector.x < 0f) width * (1f - progress) else 0f,
            revealMask = LayerRevealMaskSpec.Wipe(progress = progress)
        )
    } else {
        LayerAnimationVisualState(
            scaleYMultiplier = progress.coerceAtLeast(0.001f),
            translationY = if (vector.y < 0f) height * (1f - progress) else 0f,
            revealMask = LayerRevealMaskSpec.Wipe(progress = progress)
        )
    }
}

