// A pure clip reveal; the content never moves. In: the HOME-box band grows from the edge
// the motion starts at, on easeOutCubic over the WHOLE duration — Canva caps only its
// default window, never an explicit one, and the importer computes that window (§8.0).
// Out: the band keeps sweeping the same way (the trailing part disappears first) on
// easeInCubic, and the opacity drops to 0 only at the very end. The band is ANCHORED:
// its edge comes from the direction, so text renderers never mirror it for RTL.
LayerAnimationType.WIPE -> if (entering) {
    LayerAnimationVisualState(
        revealMask = LayerRevealMaskSpec.Wipe(
            progress = canvaEaseOutCubic(p),
            edge = canvaTrailingEdge(direction),
            anchored = true
        )
    )
} else {
    val e = canvaEaseInCubic(u)
    LayerAnimationVisualState(
        alphaMultiplier = if (u >= 1f) 0f else 1f,
        revealMask = LayerRevealMaskSpec.Wipe(
            progress = 1f - e,
            edge = canvaLeadingEdge(direction),
            anchored = true
        )
    )
}

