// The content slides into its own box while the box clips it. Our matte travels WITH the
// layer, so the HOME-box band is expressed in CONTENT space: the part of the content that
// is inside the box is its LEADING part (dir up → a band from the content's TOP edge), and
// on the way out its TRAILING part. Opacity is 1 from t = 0; the outro animates only its
// first 60% and holds hidden after. Anchored, like WIPE: the edge is absolute.
LayerAnimationType.BASELINE -> {
    val start = canvaStartOffset(direction)
    val size = if (start.y != 0f) height else width
    if (entering) {
        val e = canvaEaseOutExpo(p)
        LayerAnimationVisualState(
            translationX = start.x * size * (1f - e),
            translationY = start.y * size * (1f - e),
            revealMask = LayerRevealMaskSpec.Wipe(
                progress = e,
                edge = canvaLeadingEdge(direction),
                anchored = true
            )
        )
    } else {
        val e = canvaEaseInSine((u / 0.6f).coerceAtMost(1f))
        LayerAnimationVisualState(
            alphaMultiplier = if (u < 0.6f) 1f else 0f,
            translationX = -start.x * size * e,
            translationY = -start.y * size * e,
            revealMask = LayerRevealMaskSpec.Wipe(
                progress = 1f - e,
                edge = canvaTrailingEdge(direction),
                anchored = true
            )
        )
    }
}

