// Canva's Drift (§3): translate = lerp(-vec, +vec, t) LINEAR across the untimed window,
// ending at +vec, NOT at home. Amplitude rides on intensity (120px per unit; the importer
// stores m / 120) since the runtime cannot see the page. The loop ping-pongs the ramp.
LayerAnimationType.DRIFT -> {
    val amplitude = CANVA_CONTINUOUS_AMPLITUDE_PX * intensity
    LayerAnimationVisualState(
        translationX = vector.x * canvaLerp(-amplitude, amplitude, ramp),
        translationY = vector.y * canvaLerp(-amplitude, amplitude, ramp)
    )
}

// Canva's Tectonic (§3): translateX = lerp(-d, +d/2, t) LINEAR, `d = 120px · intensity`;
// LEFT flips the sign (Canva flips it for elements right of the page centre).
LayerAnimationType.TECTONIC -> {
    val d = CANVA_CONTINUOUS_AMPLITUDE_PX * intensity *
        (if (direction == LayerAnimationDirection.LEFT) -1f else 1f)
    LayerAnimationVisualState(translationX = canvaLerp(-d, d / 2f, ramp))
}

LayerAnimationType.TUMBLE -> {
    LayerAnimationVisualState(
        rotationDeltaDegrees = (1f - progress) * 26f * rotationSpin(animation.direction) * intensity,
        translationX = rotationSpin(animation.direction) * (1f - progress) *
            maxOf(18f, width * 0.18f) * intensity,
        translationY = -(1f - progress) * maxOf(18f, height * 0.22f) * intensity,
        alphaMultiplier = (0.08f + progress * 0.92f).coerceIn(0f, 1f)
    )
}

