// With the importer's `startRotation` / `travelX` / `travelY` (Canva's `juf`, page size and
// element rotation included): the entrance starts at that offset and eases to rest on
// easeOutCubic; the exit eases from rest to it on easeInCubic (the reverse flag is baked
// into the exit's own params). Without them: starts rotated k° (≈ -180° ± a per-layer
// hash) a page-height away, from the LEFT when the motion is RIGHT (or auto on an even
// layer), from the RIGHT otherwise.
LayerAnimationType.TUMBLE -> {
    val startRotation = animation.param(CanvaAnimationParams.START_ROTATION)
    val paramTravelX = animation.param(CanvaAnimationParams.TRAVEL_X)
    val paramTravelY = animation.param(CanvaAnimationParams.TRAVEL_Y)
    if (startRotation != null || paramTravelX != null || paramTravelY != null) {
        val k = (startRotation ?: 0.0).toFloat()
        val tx = (paramTravelX ?: 0.0).toFloat()
        val ty = (paramTravelY ?: 0.0).toFloat()
        if (entering) {
            val e = canvaEaseOutCubic(p)
            LayerAnimationVisualState(
                alphaMultiplier = e,
                rotationDeltaDegrees = k * (1f - e),
                translationX = tx * (1f - e),
                translationY = ty * (1f - e)
            )
        } else {
            val e = canvaEaseInCubic(u)
            LayerAnimationVisualState(
                alphaMultiplier = 1f - e,
                rotationDeltaDegrees = k * e,
                translationX = tx * e,
                translationY = ty * e
            )
        }
    } else {
        val k = (if (even) canvaLerp(-90f, -270f, vd) else canvaLerp(-270f, -90f, vd)) +
            canvaTumbleHashDegrees(sequenceIndex, width, height)
        val fromLeft = when (animation.direction) {
            LayerAnimationDirection.RIGHT -> true
            LayerAnimationDirection.LEFT -> false
            else -> even
        }
        val travelX = if (fromLeft) -CANVA_TUMBLE_TRAVEL_PX else CANVA_TUMBLE_TRAVEL_PX
        if (entering) {
            val e = canvaEaseOutCubic(p)
            LayerAnimationVisualState(
                alphaMultiplier = e,
                rotationDeltaDegrees = k * (1f - e),
                translationX = travelX * (1f - e)
            )
        } else {
            val e = canvaEaseInCubic(u)
            LayerAnimationVisualState(
                alphaMultiplier = 1f - e,
                rotationDeltaDegrees = -k * e,
                translationX = -travelX * e
            )
        }
    }
}

// Discrete stamps on Canva's own clock (`jtf`) — no tweening between poses — ending at
// rest; the tilt flips with the parity. Out is a hard cut to nothing.
LayerAnimationType.SCRAPBOOK -> if (entering) {
    val pose = canvaScrapbookPose(
        progress = p,
        durationMs = animation.durationMs,
        poses = animation.param(CanvaAnimationParams.POSES)?.let { floor(it).toInt() } ?: CANVA_SCRAPBOOK_POSES,
        bx = animation.param(CanvaAnimationParams.POSE_X) ?: 0.0,
        by = animation.param(CanvaAnimationParams.POSE_Y) ?: 0.0,
        sign = if (even) 1.0 else -1.0
    )
    LayerAnimationVisualState(
        translationX = pose.translationX,
        translationY = pose.translationY,
        rotationDeltaDegrees = pose.rotationDegrees
    )
} else {
    LayerAnimationVisualState(alphaMultiplier = if (u > 0f) 0f else 1f)
}

