// Canva's text-only bar (`esf`): the FULL layer box, offset along the motion axis by
// s = x < .5 ? −1 + easeInQuart(2x) : easeOutQuart(2x − 1) — in from the far side,
// covering the box at x = .5, out the other side — visible while x < 1 and clipped to the
// layer box. The text switches ON at the midpoint entering and OFF at it exiting; the hide
// is an anchored Wipe at 0/1 so the bar is untouched, and the alpha stays 1.
LayerAnimationType.BLOCK -> {
    val x = if (entering) cycleProgress.coerceIn(0f, 1f) else u
    val s = if (x < 0.5f) -1f + canvaEaseInQuart(2f * x) else canvaEaseOutQuart(2f * x - 1f)
    val shown = if (entering) x >= 0.5f else x < 0.5f
    val color = animation.param(CanvaAnimationParams.BAR_COLOR)?.let { it.toLong() and 0xFFFFFFFFL }
    val bar = if (x < 1f) {
        when (direction) {
            LayerAnimationDirection.LEFT -> LayerOverlayBarSpec(leftFraction = -s, topFraction = 0f, colorArgb = color)
            LayerAnimationDirection.DOWN -> LayerOverlayBarSpec(leftFraction = 0f, topFraction = s, colorArgb = color)
            LayerAnimationDirection.UP -> LayerOverlayBarSpec(leftFraction = 0f, topFraction = -s, colorArgb = color)
            else -> LayerOverlayBarSpec(leftFraction = s, topFraction = 0f, colorArgb = color)
        }
    } else {
        null
    }
    LayerAnimationVisualState(
        revealMask = LayerRevealMaskSpec.Wipe(progress = if (shown) 1f else 0f, anchored = true),
        overlayBar = bar
    )
}

