// كلمة واحدة — their -Word Typing One: one WORD at a time, each replacing the last.
// Their art animates nothing but per-word opacity, so the layer itself stays put and
// the whole effect rides on [glyphMotion]. The Wipe is only for surfaces that cannot
// address words (media layers, the export canvas, curved text).
LayerAnimationType.ONE_WORD -> LayerAnimationVisualState(
    revealMask = LayerRevealMaskSpec.Wipe(progress = progress),
    glyphMotion = GlyphMotionSpec(LayerAnimationType.ONE_WORD, progress, animation.durationMs)
)

// Typewriter: a text renderer reveals glyphs progressively via [textReveal]
// (chars/words stepped, cursor smooth). The alpha fade + Wipe mask stay as
// fallbacks for curved/multi-line text, media layers, and export.
// A glyph pops in whole, so there is NO layer-level fade on the text path —
// the alpha here is only a fallback for renderers that can't do a glyph
// reveal (curved text, the native export canvas), where the Wipe mask serves
// media layers.
LayerAnimationType.TYPEWRITER_CHARS ->
    typewriterVisualState(progress, TextRevealMode.CHARS, animation.durationMs)

LayerAnimationType.RANDOM -> {
    val rx = sin(cycleProgress * PI.toFloat() * 6.6f) + 0.5f * sin(cycleProgress * PI.toFloat() * 15.4f)
    val ry = cos(cycleProgress * PI.toFloat() * 8.2f) + 0.5f * sin(cycleProgress * PI.toFloat() * 18.6f)
    LayerAnimationVisualState(
        translationX = rx * maxOf(4f, width * 0.02f) * intensity,
        translationY = ry * maxOf(4f, height * 0.02f) * intensity,
        rotationDeltaDegrees = rx * 3f * intensity
    )
}

