    revealMask = LayerRevealMaskSpec.Wipe(progress = progress),
    glyphMotion = GlyphMotionSpec(animation.type, progress, animation.durationMs)
)

// The character effects animate each GLYPH, never the layer, so the layer-level
// state stays neutral and the whole effect rides on [glyphMotion]. As with the
// typewriters, the Wipe is only for surfaces that can't address glyphs; a renderer
// that honours [glyphMotion] must ignore it rather than apply both.
LayerAnimationType.CH_POSITION_FADE,
LayerAnimationType.CH_SCALE_FADE,
// ASCEND rides the same path: the glyph motion is the effect on text, and the Wipe is the
// fallback for surfaces with no glyphs to move (media layers, curved text).
LayerAnimationType.ASCEND -> LayerAnimationVisualState(
    revealMask = LayerRevealMaskSpec.Wipe(progress = progress),
    glyphMotion = GlyphMotionSpec(animation.type, progress, animation.durationMs)
)

// The wave is a loop with no opacity at all in their art, and nothing about it
// survives without glyphs — a media layer simply sits still, as WAVE already
// covers whole-layer floating.
LayerAnimationType.CH_WIGGLE_Y -> LayerAnimationVisualState(
    glyphMotion = GlyphMotionSpec(animation.type, cycleProgress, animation.durationMs)
)

runtime.variables:
val animation = playbackState.animation ?: return LayerAnimationVisualState()
// Wide enough for the importer's `intensity = amplitude / 120` on DRIFT/TECTONIC (0.1..4);
// the picker itself always writes 1.
val intensity = animation.intensity.coerceIn(0.1f, 4f)
val width = layerWidthPx.coerceAtLeast(1f)
val height = layerHeightPx.coerceAtLeast(1f)
val direction = if (animation.direction == LayerAnimationDirection.DEFAULT) {
    animation.type.preset().direction
} else {
    animation.direction
}
val vector = resolveAnimationVector(direction)
val cycleProgress = playbackState.progress.coerceIn(0f, 1f)
val oneShotProgress = applyLayerAnimationEasing(cycleProgress, animation.easing)
val cycleWave = applyLayerAnimationEasing(pingPongProgress(cycleProgress), animation.easing)
val progress = if (animation.infinite) cycleWave else oneShotProgress
val wave = sin(cycleProgress * 2f * PI.toFloat())
val pingPong = pingPongProgress(cycleProgress)
// Canva's continuous presets (BREATHE / DRIFT / TECTONIC): one loop cycle is their untimed
// A → B → A ramp, LINEAR and triangular (not the raised cosine), so a picked loop cycles
// seamlessly; a one-shot slot plays the single A → B ramp.
val ramp = if (animation.infinite) 1f - abs(2f * cycleProgress - 1f) else cycleProgress

helpers.resolveAnimationVector:
private fun resolveAnimationVector(direction: LayerAnimationDirection): Offset =
    when (direction) {
        LayerAnimationDirection.LEFT -> Offset(-1f, 0f)
        LayerAnimationDirection.RIGHT -> Offset(1f, 0f)
        LayerAnimationDirection.DOWN -> Offset(0f, 1f)
        LayerAnimationDirection.UP -> Offset(0f, -1f)
        else -> Offset(0f, 0f)
    }

helpers.rotationSpin:
private fun rotationSpin(direction: LayerAnimationDirection): Float =
    when (direction) {
        LayerAnimationDirection.COUNTERCLOCKWISE,
        LayerAnimationDirection.LEFT -> -1f
        else -> 1f
    }

helpers.pingPongProgress:
private fun pingPongProgress(progress: Float): Float {
    val clamped = progress.coerceIn(0f, 1f)
    return (0.5f - cos(clamped * PI.toFloat() * 2f) / 2f).coerceIn(0f, 1f)
}

helpers.applyLayerAnimationEasing:
private fun applyLayerAnimationEasing(
    progress: Float,
    easing: LayerAnimationEasing
): Float {
    val clamped = progress.coerceIn(0f, 1f)
    return when (easing) {
        LayerAnimationEasing.LINEAR,
        LayerAnimationEasing.DEFAULT -> clamped
        LayerAnimationEasing.SOFT_OUT -> {
            val inverse = 1f - clamped
            1f - inverse * inverse * inverse * inverse
        }
        LayerAnimationEasing.EASE_OUT -> {
            val inverse = 1f - clamped
            1f - inverse * inverse * inverse
        }
        LayerAnimationEasing.EASE_IN -> clamped * clamped
        LayerAnimationEasing.EASE_IN_OUT -> {
            if (clamped < 0.5f) {
                4f * clamped * clamped * clamped
            } else {
                val inverse = -2f * clamped + 2f
                1f - (inverse * inverse * inverse / 2f)
            }
        }
        LayerAnimationEasing.SOFT_IN_OUT -> 0.5f - cos(PI.toFloat() * clamped) / 2f
    }
}

canva.easings:
// ---- Canva's easings, exact (§1) ----------------------------------------------------------

internal fun canvaEaseInQuad(u: Float): Float = u * u
internal fun canvaEaseOutQuad(u: Float): Float = u * (2f - u)
internal fun canvaEaseInOutQuad(u: Float): Float =
    if (u < 0.5f) 2f * u * u else (4f - 2f * u) * u - 1f
internal fun canvaEaseInCubic(u: Float): Float = u * u * u
internal fun canvaEaseOutCubic(u: Float): Float = (u - 1f).pow(3) + 1f
internal fun canvaEaseInQuart(u: Float): Float = u * u * u * u
internal fun canvaEaseOutQuart(u: Float): Float = 1f - (1f - u).pow(4)
/**
 * `1 − 2^(−10u)`, pinned to 1 at u = 1: the bare formula ends at 1 − 2⁻¹⁰, and a tween that has
 * ENDED returns its END value in Canva (§2), so BASELINE must land exactly home — the timeline
 * holds the entrance's last frame, and the 1/1024 it left behind was a permanent sub-pixel
 * offset plus a hairline of clipped content on every Baseline layer at rest.
 */
internal fun canvaEaseOutExpo(u: Float): Float = if (u >= 1f) 1f else 1f - 2f.pow(-10f * u)
internal fun canvaEaseInSine(u: Float): Float = 1f - cos(u * PI.toFloat() / 2f)

/** `-2^(10(u-1)/amp) · sin((u - 1.1)·5π)`, pinned to 0 and 1 at the ends. */
internal fun canvaElasticIn(u: Float, amplitude: Float = 1f): Float = when {
    u <= 0f -> 0f
    u >= 1f -> 1f
    else -> -(2f.pow(10f * (u - 1f) / amplitude)) * sin((u - 1.1f) * 5f * PI.toFloat())
}

/** `2^(-10u/amp) · sin((u - 0.1)·5π) + 1`, pinned to 0 and 1 at the ends; overshoots to ~1.28. */
internal fun canvaElasticOut(u: Float, amplitude: Float = 1f): Float = when {
    u <= 0f -> 0f
    u >= 1f -> 1f
    else -> 2f.pow(-10f * u / amplitude) * sin((u - 0.1f) * 5f * PI.toFloat()) + 1f
}

internal fun canvaLerp(from: Float, to: Float, t: Float): Float = from + (to - from) * t

canva.constants:
// ---- Constants the runtime substitutes for the page Canva can see and we cannot -------------

/** RISE / PAN travel, flat px — measured identical on a 162px title and a 56px caption. */
internal const val CANVA_RISE_TRAVEL_PX = 80f

/** BLUR's peak Gaussian radius, design px. */
internal const val CANVA_BLUR_RADIUS_PX = 32f

/** SUCCESSION's peak Gaussian radius, design px. */
internal const val CANVA_SUCCESSION_BLUR_PX = 24f

/** TUMBLE travels from `max(pageW, pageH)` away — the standard story height stands in. */
internal const val CANVA_TUMBLE_TRAVEL_PX = 1920f

/** STOMP starts at `max(4, pageW · 1.5 / w)` — the standard story width stands in (1080 · 1.5). */
internal const val CANVA_STOMP_PAGE_WIDTH_PX = 1620f

/** SCRAPBOOK stamps three poses when the element sits near the page centre — assumed (`poses` overrides). */
internal const val CANVA_SCRAPBOOK_POSES = 3

/** SCRAPBOOK's stamp offset, design px. */
internal const val CANVA_SCRAPBOOK_OFFSET_PX = 50f

/** DRIFT / TECTONIC amplitude per unit of intensity; the importer stores `intensity = m / 120`. */
internal const val CANVA_CONTINUOUS_AMPLITUDE_PX = 120f

/** FLICKER's hold at the dim value, ms. */
internal const val CANVA_FLICKER_HOLD_MS = 200f

/** WIGGLE at Canva's default slider (t = .5): 55 steps and `lerp(.5, 1.8, .5)` amplitude. */
internal const val CANVA_WIGGLE_STEPS = 55
internal const val CANVA_WIGGLE_AMPLITUDE = 1.15f

canva.hashes:
// ---- Per-layer hashes (Canva hashes the element's geometry; we hash what both platforms have) ---

/** Even/odd of the layer's z-index — Canva's element-index parity. Negative-safe. */
internal fun canvaLayerParityEven(layerIndex: Int): Boolean = layerIndex.mod(2) == 0

/** TUMBLE's pseudo-random start angle: `|cos(idx) · w · h| mod 360`, computed in doubles like the web. */
internal fun canvaTumbleHashDegrees(layerIndex: Int, width: Float, height: Float): Float =
    (abs(cos(layerIndex.toDouble()) * width.toDouble() * height.toDouble()) % 360.0).toFloat()

/** WIGGLE's per-step random: `|cos(seed) · w · h| mod 1`, computed in doubles like the web. */
internal fun canvaWiggleHash(seed: Int, width: Float, height: Float): Float =
    canvaWiggleRandom(seed, null, width, height).toFloat()

/**
 * Canva's `rqf` random for step [step]: `|cos(s) · P| mod 1` with the importer's hash product
 * P = [seed] (w·h·max(top,1)·max(left,1) of the element), or — for a picker-made animation, which
 * carries no seed — the layer's own `w · h`, so both platforms still agree frame for frame.
 */
internal fun canvaWiggleRandom(step: Int, seed: Double?, width: Float, height: Float): Double =
    if (seed != null) {
        abs(cos(step.toDouble()) * seed) % 1.0
    } else {
        abs(cos(step.toDouble()) * width.toDouble() * height.toDouble()) % 1.0
    }

canva.directionHelpers:
// ---- Direction helpers -------------------------------------------------------------------------

/** Canva's Vd slider (0..1, default .5) rides on `intensity = 0.5 + Vd`. */
internal fun canvaIntensitySlider(intensity: Float): Float = (intensity - 0.5f).coerceIn(0f, 1f)

private data class CanvaVector(val x: Float, val y: Float)

/** The spec's direction, or the type's own preset direction when the spec's is not an axis. */
private fun canvaAxisDirection(type: LayerAnimationType, direction: LayerAnimationDirection): LayerAnimationDirection =
    when (direction) {
        LayerAnimationDirection.UP,
        LayerAnimationDirection.DOWN,
        LayerAnimationDirection.LEFT,
        LayerAnimationDirection.RIGHT -> direction
        else -> type.preset().direction
    }

/**
 * Where the element STARTS relative to home for a motion in [direction] — Canva's `urf`: the
 * direction is the way the element MOVES, so UP starts BELOW (+y is down).
 */
private fun canvaStartOffset(direction: LayerAnimationDirection): CanvaVector = when (direction) {
    LayerAnimationDirection.UP -> CanvaVector(0f, 1f)
    LayerAnimationDirection.DOWN -> CanvaVector(0f, -1f)
    LayerAnimationDirection.LEFT -> CanvaVector(1f, 0f)
    LayerAnimationDirection.RIGHT -> CanvaVector(-1f, 0f)
    else -> CanvaVector(0f, 0f)
}

/** The layer edge in the direction of motion (motion RIGHT → the RIGHT edge). */
private fun canvaLeadingEdge(direction: LayerAnimationDirection): WipeEdge = when (direction) {
    LayerAnimationDirection.UP -> WipeEdge.TOP
    LayerAnimationDirection.DOWN -> WipeEdge.BOTTOM
    LayerAnimationDirection.LEFT -> WipeEdge.LEFT
    else -> WipeEdge.RIGHT
}

/** The layer edge the motion starts from (motion RIGHT → the LEFT edge). */
private fun canvaTrailingEdge(direction: LayerAnimationDirection): WipeEdge = when (direction) {
    LayerAnimationDirection.UP -> WipeEdge.BOTTOM
    LayerAnimationDirection.DOWN -> WipeEdge.TOP
    LayerAnimationDirection.LEFT -> WipeEdge.RIGHT
    else -> WipeEdge.LEFT
}

/**
 * True for the presets whose one-shot entrance AND exit are Canva's own tweens (§2). SHIFT and
 * SKATE are our mirrors of RISE and PAN (the same tween, direction DOWN / LEFT), so they ride
 * the same branch and stay exact mirrors now that RISE/PAN are Canva's. BLOCK (§8.3) plays
 * Canva's bar in every slot, a loop included.
 */
internal fun LayerAnimationType.isCanvaEnterExitPreset(): Boolean = when (this) {
    LayerAnimationType.RISE,
    LayerAnimationType.SHIFT,
    LayerAnimationType.PAN,
    LayerAnimationType.SKATE,
    LayerAnimationType.FADE,
    LayerAnimationType.POP,
    LayerAnimationType.WIPE,
    LayerAnimationType.BLUR,
    LayerAnimationType.SUCCESSION,
    LayerAnimationType.BASELINE,
    LayerAnimationType.TUMBLE,
    LayerAnimationType.NEON,
    LayerAnimationType.SCRAPBOOK,
    LayerAnimationType.STOMP,
    LayerAnimationType.BLOCK -> true
    else -> false
}

canva.neon:
// ---- NEON: a sign flickering on, as Canva's linear opacity tween list --------------------------

private class CanvaNeonTween(val delay: Float, val duration: Float, val from: Float, val to: Float) {
    val end: Float get() = delay + duration
}

/**
 * Canva's tween-list rule: the LAST tween (by delay) whose delay ≤ t owns the property — before
 * its delay its start value, after its end its end value, between them the linear ramp. Before
 * the very first tween, that tween's start value shows.
 */
private fun List<CanvaNeonTween>.valueAt(t: Float): Float {
    val active = lastOrNull { it.delay <= t } ?: return first().from
    val local = if (active.duration <= 0f) 1f else ((t - active.delay) / active.duration).coerceIn(0f, 1f)
    return active.from + (active.to - active.from) * local
}

/**
 * Intro opacity at [p]. `c = intro / lerp(10, 26, Vd)`, `n = floor(lerp(1, 4, Vd))`; the list is
 * built in units of `c`. Should the list overrun the intro (it does at the slider's low end), the
 * whole list is fitted to it so the layer is always fully on at p = 1. (The per-UNIT flicker of a
 * writing style is Canva's literal `Esf` — see [canvaNeonUnitIntro].)
 */
internal fun canvaNeonIntroOpacity(p: Float, vd: Float, parityEven: Boolean): Float {
    val steps = canvaLerp(10f, 26f, vd)
    val n = floor(canvaLerp(1f, 4f, vd)).toInt()
    val tweens = mutableListOf<CanvaNeonTween>()
    var f = 0f
    for (i in 0 until n) {
        if (i % 2 == 0) {
            tweens += CanvaNeonTween(delay = f, duration = 3f, from = 0f, to = 1f)
            tweens += CanvaNeonTween(delay = f + 4f, duration = 1f, from = if (parityEven) 1f else 0f, to = 0f)
            f += 5f
        } else {
            val hold = if (parityEven) 1f else 0.75f
            tweens += CanvaNeonTween(delay = f + 1f, duration = 1f, from = hold, to = hold)
            tweens += CanvaNeonTween(delay = f + 3f, duration = 1f, from = 0f, to = 0f)
            f += 4f
        }
    }
    tweens += if (parityEven) {
        CanvaNeonTween(delay = f + 4f, duration = 3f, from = 0f, to = 1f)
    } else {
        CanvaNeonTween(delay = f + 5f, duration = 4f, from = 0f, to = 1f)
    }
    val span = maxOf(steps, tweens.maxOf { it.end })
    return tweens.valueAt(p.coerceIn(0f, 1f) * span).coerceIn(0f, 1f)
}

/**
 * Outro opacity at [u]. `d = outro / lerp(4, 8, Vd)` (default outro / 6); the schedule is fitted
 * to the outro should it overrun, so the layer is always off at u = 1.
 */
internal fun canvaNeonOutroOpacity(u: Float, vd: Float, parityEven: Boolean): Float {
    val steps = canvaLerp(4f, 8f, vd)
    return if (parityEven) {
        val x = u.coerceIn(0f, 1f) * maxOf(steps, 5f)
        when {
            x < 1.1f -> 1f
            x < 3f -> 0f
            x < 5f -> 0.5f
            else -> 0f
        }
    } else {
        val x = u.coerceIn(0f, 1f) * maxOf(steps, 4.1f)
        when {
            x < 1f -> 1f
            x < 3f -> canvaLerp(1f, 0.5f, (x - 1f) / 2f)
            x < 4f -> 0.5f
            x < 4.1f -> canvaLerp(0.5f, 0f, (x - 4f) / 0.1f)
            else -> 0f
        }
    }
}

canva.params:
/**
 * The keys of [LayerAnimationSpec.params] — docs/canva-animation-parity.md §8.1 in the web
 * dashboard, which is the single source of truth. Only the Canva importer writes them; a spec
 * the picker builds never carries any, and an absent key always means "the behaviour the picker
 * already gets". Unknown keys are ignored.
 */
object CanvaAnimationParams {
    /** Loop slot: 1 = runs alongside the entrance/exit for the whole visible window (§8.2). */
    const val CONCURRENT = "concurrent"

    /** Loop slot: added to the layer-local clock of a concurrent loop. */
    const val PHASE_MS = "phaseMs"

    /** Loop slot: extra repeating effects on the same layer, value = cycle ms (rotate < 0 = CCW). */
    const val STACK_ROTATE = "stackRotate"
    const val STACK_FLICKER = "stackFlicker"
    const val STACK_PULSE = "stackPulse"
    const val STACK_WIGGLE = "stackWiggle"

    /** Loop slot: t = (Vd + 1) / 2 of the stacked flicker / wiggle. */
    const val STACK_FLICKER_T = "stackFlickerT"
    const val STACK_WIGGLE_T = "stackWiggleT"

    /** Loop slot: clock offset for the stacked effects. */
    const val STACK_PHASE_MS = "stackPhaseMs"

    /** BREATHE / DRIFT / TECTONIC (concurrent): the time-based ramp, ms layer-local, eases per §1 ids. */
    const val R1_FROM = "r1From"
    const val R1_TO = "r1To"
    const val R1_START = "r1Start"
    const val R1_DUR = "r1Dur"
    const val R1_EASE = "r1Ease"
    const val R2_TO = "r2To"
    const val R2_START = "r2Start"
    const val R2_DUR = "r2Dur"
    const val R2_EASE = "r2Ease"

    /** BREATHE: vertical drift (px) on the same ramp timing. */
    const val Y1_FROM = "y1From"
    const val Y1_TO = "y1To"
    const val Y2_TO = "y2To"

    /** FADE: 1 = LINEAR in and out. */
    const val FADE_EASE = "fadeEase"

    /** FADE / BLUR / SUCCESSION / NEON: the writing style — 1 character, 2 word, 3 line. */
    const val UNIT = "unit"

    /** Same types: 1 = stretch the unit schedule to fill the duration (an explicit Canva duration). */
    const val FILL = "fill"

    /** NEON / SCRAPBOOK / TUMBLE: Canva's sequence index XH (parity, hashes); replaces layerIndex. */
    const val XH = "xh"

    /** WIGGLE, NEON units, stacked wiggle: Canva's hash product P = w·h·max(top,1)·max(left,1). */
    const val SEED = "seed"

    /** TUMBLE: start offset (entrance) / end offset (exit) — degrees, px, px. */
    const val START_ROTATION = "startRotation"
    const val TRAVEL_X = "travelX"
    const val TRAVEL_Y = "travelY"

    /** STOMP: the starting scale s0. */
    const val START_SCALE = "startScale"

    /** SCRAPBOOK: g (2 or 3) and the b vector (px). */
    const val POSES = "poses"
    const val POSE_X = "poseX"
    const val POSE_Y = "poseY"

    /** BLOCK: ARGB 0xAARRGGBB as a number; absent = the text colour. */
    const val BAR_COLOR = "barColor"
}

/** A finite param, or null when absent (or not a number the runtime can use). */
internal fun LayerAnimationSpec.param(key: String): Double? = params[key]?.takeIf { it.isFinite() }

/** True for a LOOP slot the importer marked as running alongside the entrance and exit (§8.2). */
fun LayerAnimationSpec.isCanvaConcurrentLoop(): Boolean = param(CanvaAnimationParams.CONCURRENT) == 1.0

/** Canva's element index for parity / hashes: the spec's `xh` when present, else the layer's z-index. */
internal fun LayerAnimationSpec.canvaSequenceIndex(layerIndex: Int): Int =
    param(CanvaAnimationParams.XH)?.let { floor(it).toInt() } ?: layerIndex

/**
 * [LayerAnimationSpec.intensity] as the DOUBLE the importer wrote.
 *
 * ★The model stores intensity as a Float, but Canva's `t`/`Vd` feed `floor(lerp(…))` step counts
 * (WIGGLE's n, NEON's n) whose boundaries sit exactly on "nice" slider values: 1.2 read as a Float
 * is 1.2000000477, which floors WIGGLE to 73 steps where Canva (and the web, which keeps the JSON
 * double) floor to 72. Snapping to six decimals recovers the JSON value for every intensity the
 * importer writes (0.5 + t with a short t) on both platforms identically.
 */
internal fun canvaExactIntensity(intensity: Float): Double =
    (intensity.toDouble() * 1_000_000.0).roundToLong() / 1_000_000.0

/** Canva's Vd / t from the spec intensity: `clamp(intensity − .5, 0, 1)` in double precision. */
internal fun canvaSliderT(intensity: Float): Double = (canvaExactIntensity(intensity) - 0.5).coerceIn(0.0, 1.0)

/**
 * A Float progress as the decimal DOUBLE the web holds for the same instant — same snapping as
 * [canvaExactIntensity], so a schedule sampled at p = 0.3 lands on τ = 0.3 · D exactly on both
 * platforms instead of one Float ulp away (which matters only at a tween's boundary, where it
 * decides which tween has started).
 */
internal fun canvaExactProgress(progress: Float): Double =
    (progress.coerceIn(0f, 1f).toDouble() * 1_000_000.0).roundToLong() / 1_000_000.0

canva.tweens:
/*
 * Canva's tween machinery, ported literally and in DOUBLE precision (docs/canva-animation-parity.md
 * §8 in the web dashboard): `aqf` evaluates one tween, `Xpf` picks the latest-started tween, `Zqf`
 * fits a schedule into a window (floors included), `Fqf`/`Gqf` drop overlapping tweens, and `bqf`
 * is the easing table by id (§1). The web runs the same functions over JS numbers — also IEEE
 * doubles — so both runtimes land on the same floors and pick the same winners.
 */

/** Canva's easing ids (`bv`, §1). 16–22 exist in Canva and are linear there too. */
internal const val CANVA_EASE_LINEAR = 1
internal const val CANVA_EASE_IN_QUAD = 2
internal const val CANVA_EASE_OUT_QUAD = 3
internal const val CANVA_EASE_IN_OUT_QUAD = 4
internal const val CANVA_EASE_IN_CUBIC = 5
internal const val CANVA_EASE_OUT_CUBIC = 6
internal const val CANVA_EASE_IN_QUART = 7
internal const val CANVA_EASE_OUT_QUART = 8
internal const val CANVA_EASE_OUT_EXPO = 9
internal const val CANVA_EASE_IN_SINE = 10
internal const val CANVA_EASE_ELASTIC_IN = 11
internal const val CANVA_EASE_ELASTIC_OUT = 12
internal const val CANVA_EASE_ELASTIC_IN_07 = 13
internal const val CANVA_EASE_ELASTIC_OUT_07 = 14
internal const val CANVA_EASE_IN_OUT_CUBIC = 15

/** Canva's easing [id] at u ∈ [0, 1] (`bqf`, §1). Unknown ids are linear, as in Canva. */
internal fun canvaEase(id: Int, u: Double): Double = when (id) {
    CANVA_EASE_IN_QUAD -> u * u
    CANVA_EASE_OUT_QUAD -> u * (2.0 - u)
    CANVA_EASE_IN_OUT_QUAD -> if (u < 0.5) 2.0 * u * u else (4.0 - 2.0 * u) * u - 1.0
    CANVA_EASE_IN_CUBIC -> u.pow(3)
    CANVA_EASE_OUT_CUBIC -> (u - 1.0).pow(3) + 1.0
    CANVA_EASE_IN_QUART -> u.pow(4)
    CANVA_EASE_OUT_QUART -> -((u - 1.0).pow(4) - 1.0)
    CANVA_EASE_OUT_EXPO -> -(2.0.pow(u * -10.0)) + 1.0
    CANVA_EASE_IN_SINE -> 1.0 - cos(u * (PI / 2.0))
    CANVA_EASE_ELASTIC_IN -> canvaElasticInD(u, 1.0)
    CANVA_EASE_ELASTIC_OUT -> canvaElasticOutD(u, 1.0)
    CANVA_EASE_ELASTIC_IN_07 -> canvaElasticInD(u, 0.7)
    CANVA_EASE_ELASTIC_OUT_07 -> canvaElasticOutD(u, 0.7)
    CANVA_EASE_IN_OUT_CUBIC -> if (u < 0.5) 4.0 * u.pow(3) else 1.0 - (-2.0 * u + 2.0).pow(3) / 2.0
    else -> u
}

private fun canvaElasticInD(u: Double, amplitude: Double): Double = when {
    u == 0.0 -> 0.0
    u == 1.0 -> 1.0
    else -> -(2.0.pow(10.0 * (u - 1.0) * (1.0 / amplitude))) * sin((u - 1.1) * 5.0 * PI)
}

private fun canvaElasticOutD(u: Double, amplitude: Double): Double = when {
    u == 0.0 -> 0.0
    u == 1.0 -> 1.0
    else -> 2.0.pow(-10.0 * u * (1.0 / amplitude)) * sin((u - 0.1) * 5.0 * PI) + 1.0
}

/** Canva's `cv`: `a + (b − a)·t`, in double precision. */
internal fun canvaLerpD(from: Double, to: Double, t: Double): Double = from + (to - from) * t

/** One Canva tween of ONE property: [from] → [to] over [delay, delay + duration] on easing [easing]. */
internal class CanvaTween(
    val delay: Double,
    val duration: Double,
    val from: Double,
    val to: Double,
    val easing: Int = CANVA_EASE_LINEAR
) {
    /**
     * Canva's `aqf`: before the delay the START value, once the tween has run its duration its
     * exact END value (so a curve that never quite reaches 1 — easeOutExpo — still lands), eased
     * in between. A zero or negative duration jumps straight to the end.
     */
    fun valueAt(t: Double): Double {
        if (t < delay) return from
        val elapsed = t - delay
        return if (elapsed >= duration) to else from + (to - from) * canvaEase(easing, elapsed / duration)
    }

    /**
     * Canva's `Zqf` against a window that starts at [windowDelay]: delay and duration scaled by
     * [factor] and FLOORED, the delay never negative and the duration never below 1ms.
     */
    fun fitted(factor: Double, windowDelay: Double = 0.0): CanvaTween = CanvaTween(
        delay = max(0.0, floor(windowDelay + (delay - windowDelay) * factor)),
        duration = max(1.0, floor(duration * factor)),
        from = from,
        to = to,
        easing = easing
    )

    val end: Double get() = delay + duration
}

/**
 * Canva's `Xpf` over one property's tweens: the LAST tween (by delay) that has started owns the
 * property — so between two tweens the earlier one's END value holds — and before the very first
 * tween its START value shows. [tweensByDelayDesc] must be sorted by delay, DESCENDING and stable
 * (Canva's `Rpf` sort); [canvaSortedForEvaluation] does exactly that. Empty lists read [fallback].
 */
internal fun canvaLatestTweenValue(t: Double, tweensByDelayDesc: List<CanvaTween>, fallback: Double = 0.0): Double {
    if (tweensByDelayDesc.isEmpty()) return fallback
    var chosen = tweensByDelayDesc[0]
    for (tween in tweensByDelayDesc) {
        chosen = tween
        if (t >= tween.delay) return tween.valueAt(t)
    }
    return chosen.valueAt(t)
}

/** Canva's `Rpf` sort: by delay, descending, stable (ties keep their order). */
internal fun List<CanvaTween>.canvaSortedForEvaluation(): List<CanvaTween> = sortedByDescending { it.delay }

/** JavaScript's `Math.round(x * 1E3) / 1E3` (half-up, unlike Kotlin's half-even `round`). */
private fun canvaRound3(x: Double): Double = floor(x * 1000.0 + 0.5) / 1000.0

/**
 * Canva's `Fqf` for two tweens of the same property: do their windows overlap (3-decimal rounding,
 * touching ends do NOT overlap)?
 */
internal fun canvaTweensOverlap(a: CanvaTween, b: CanvaTween): Boolean {
    val c = canvaRound3(b.delay)
    val d = canvaRound3(a.delay + a.duration)
    return canvaRound3(a.delay) < canvaRound3(b.delay + b.duration) && c < d
}

/**
 * Canva's `Gqf`: walks the list from its END and keeps a tween only if it overlaps none already
 * kept — later tweens win over earlier ones they collide with. The result is in reverse order,
 * exactly as Canva's `reduceRight` leaves it (it only matters for stable ties, of which the
 * dedupe leaves none).
 */
internal fun List<CanvaTween>.canvaDeduped(): List<CanvaTween> {
    val kept = ArrayList<CanvaTween>(size)
    for (index in indices.reversed()) {
        val candidate = this[index]
        if (kept.none { canvaTweensOverlap(candidate, it) }) kept += candidate
    }
    return kept
}

/**
 * The time-based ramp of Canva's continuous presets (§8.2): before [start1] the ramp sits at
 * [from1]; the second segment (when [twoSegment]) owns everything from [start2]; each segment
 * eases to its end over its duration and a duration ≤ 0 jumps straight to its end value.
 */
internal fun canvaRampValue(
    tau: Double,
    from1: Double,
    to1: Double,
    start1: Double,
    dur1: Double,
    ease1: Int,
    twoSegment: Boolean,
    to2: Double,
    start2: Double,
    dur2: Double,
    ease2: Int
): Double = when {
    tau < start1 -> from1
    twoSegment && tau >= start2 -> canvaRampSegment(to1, to2, tau - start2, dur2, ease2)
    else -> canvaRampSegment(from1, to1, tau - start1, dur1, ease1)
}

private fun canvaRampSegment(from: Double, to: Double, elapsed: Double, duration: Double, ease: Int): Double =
    if (duration <= 0.0 || elapsed >= duration) to else from + (to - from) * canvaEase(ease, elapsed / duration)

/** `τ mod m` for a positive [modulus], never negative (a phase can put τ before 0). */
internal fun canvaFloorMod(value: Double, modulus: Double): Double {
    if (modulus <= 0.0) return 0.0
    val r = value - modulus * floor(value / modulus)
    return if (r >= modulus) 0.0 else r
}

canva.writingStyles:
/*
 * Canva's text writing styles — per character (1), word (2) or line (3) — for FADE, BLUR,
 * SUCCESSION and NEON (docs/canva-animation-parity.md §8.4 in the web dashboard).
 *
 * Two pure halves, both ported literally from Canva's bundle so the web can mirror them byte for
 * byte: [canvaTextUnits] is `crf` (which unit each grapheme belongs to), and [CanvaUnitSchedule]
 * is the per-unit tween lists of `Crf` / `gsf` / `ttf` (`ptf`, `qtf`, `rtf`, `stf`) / `Gsf`
 * (`Esf`, `Fsf`), fitted into the slot by `$qf` / `Zqf` / `Yqf` (NEON also deduped by `Gqf`) and
 * evaluated with `Xpf`'s hold rule at τ = rawProgress · durationMs. Renderers only ask two
 * questions: which unit is this glyph, and what does that unit look like now.
 */

// ---- Units: Canva's `crf` -----------------------------------------------------------------------

/**
 * Every grapheme of a text with its Canva unit. Built by [canvaTextUnits]; the renderers draw per
 * grapheme (the clip unit) with the visual of its unit.
 */
class CanvaTextUnitMap internal constructor(
    /** The real graphemes in text order — the paragraph separators are not graphemes. */
    val graphemes: List<String>,
    /** UTF-16 offset of each grapheme in the source text. */
    val graphemeStarts: IntArray,
    /** Whitespace graphemes occupy a unit but draw nothing. */
    val graphemeIsBlank: BooleanArray,
    /** Canva's unit index (`trb`) of each grapheme. */
    val unitOfGrapheme: IntArray,
    /** N = the last item's unit + 1 — the per-paragraph pseudo newline items count too. */
    val unitCount: Int
) {
    /** UTF-16 end offset (exclusive) of grapheme [index]. */
    fun graphemeEnd(index: Int): Int = graphemeStarts[index] + graphemes[index].length
}

private const val ZERO_WIDTH_JOINER = 0x200D

/**
 * The grapheme rule of §8.4, identical on every platform: a base code point plus every following
 * combining mark (Unicode Mn / Mc / Me, see [isCanvaCombiningMark]); a ZERO WIDTH JOINER attaches
 * to the cluster before it AND pulls the next code point in; variation selectors attach. Nothing
 * else joins (emoji modifiers, regional-indicator pairs and Hangul jamo split) — deliberately
 * simple, so that the web's port splits exactly the same way. Returns the UTF-16 start of every
 * cluster followed by [text]'s length.
 */
internal fun canvaGraphemeBoundaries(text: String): IntArray {
    val bounds = ArrayList<Int>(text.length + 1)
    var index = 0
    var joinNext = false
    while (index < text.length) {
        val codePoint = canvaCodePointAt(text, index)
        val attaches = bounds.isNotEmpty() && (
            joinNext ||
                codePoint == ZERO_WIDTH_JOINER ||
                isCanvaCombiningMark(codePoint) ||
                isCanvaVariationSelector(codePoint)
            )
        if (!attaches) bounds += index
        joinNext = codePoint == ZERO_WIDTH_JOINER
        index += if (codePoint >= 0x10000) 2 else 1
    }
    bounds += text.length
    return bounds.toIntArray()
}

/** [text] split by the §8.4 grapheme rule (use on a single paragraph, or see [canvaTextUnits]). */
fun canvaGraphemes(text: String): List<String> {
    val bounds = canvaGraphemeBoundaries(text)
    return List(bounds.size - 1) { text.substring(bounds[it], bounds[it + 1]) }
}

private fun canvaCodePointAt(text: String, index: Int): Int {
    val high = text[index]
    if (high.isHighSurrogate() && index + 1 < text.length) {
        val low = text[index + 1]
        if (low.isLowSurrogate()) return ((high.code - 0xD800) shl 10) + (low.code - 0xDC00) + 0x10000
    }
    return high.code
}

private fun isCanvaVariationSelector(codePoint: Int): Boolean =
    codePoint in 0xFE00..0xFE0F || codePoint in 0xE0100..0xE01EF

/** Unicode White_Space (the property, not Java's `isWhitespace`): Canva's `asi = /\s/` on an item. */
private fun isCanvaWhiteSpace(codePoint: Int): Boolean =
    codePoint in 0x09..0x0D || codePoint == 0x20 || codePoint == 0x85 || codePoint == 0xA0 ||
        codePoint == 0x1680 || codePoint in 0x2000..0x200A || codePoint == 0x2028 ||
        codePoint == 0x2029 || codePoint == 0x202F || codePoint == 0x205F || codePoint == 0x3000

/**
 * Canva's `$ri` CJK test (Han, CJK punctuation, Hiragana, Katakana and friends), code point for
 * code point: U+4E00–9FCC, U+3000–303F, U+3041–3096, U+309D–309F, U+1B001, U+1F200,
 * U+30A1–30FA, U+30FD–30FF, U+31F0–31FF, U+32D0–32FE, U+3300–3357, U+FF66–FF6F, U+FF71–FF9D, U+1B000.
 */
private fun isCanvaCjk(codePoint: Int): Boolean =
    codePoint in 0x4E00..0x9FCC || codePoint in 0x3000..0x303F ||
        codePoint in 0x3041..0x3096 || codePoint in 0x309D..0x309F ||
        codePoint == 0x1B001 || codePoint == 0x1F200 ||
        codePoint in 0x30A1..0x30FA || codePoint in 0x30FD..0x30FF || codePoint in 0x31F0..0x31FF ||
        codePoint in 0x32D0..0x32FE || codePoint in 0x3300..0x3357 || codePoint in 0xFF66..0xFF6F ||
        codePoint in 0xFF71..0xFF9D || codePoint == 0x1B000

/** Canva tests the whole item string with an unanchored regex: ANY code point decides. */
private inline fun String.anyCanvaCodePoint(predicate: (Int) -> Boolean): Boolean {
    var index = 0
    while (index < length) {
        val codePoint = canvaCodePointAt(this, index)
        if (predicate(codePoint)) return true
        index += if (codePoint >= 0x10000) 2 else 1
    }
    return false
}

/**
 * Canva's `crf` for writing style [unit] (1 character, 2 word, 3 line):
 *
 * * paragraphs = `(text + "\n").split("\n")` minus the last piece; every paragraph contributes a
 *   PSEUDO newline item (whitespace, not CJK) followed by its graphemes;
 * * word index: w₀ = 0, wⱼ = wⱼ₋₁ + 1 when item j−1 is whitespace or CJK, or its CJK-ness differs
 *   from item j's; unit: character uⱼ = j, word uⱼ = wⱼ, line u₀ = 0 and uⱼ = uⱼ₋₁ + 1 when item
 *   j−1's line is lower than item j's;
 * * N = the last item's unit + 1. Whitespace and pseudo items occupy units but draw nothing, so the
 *   first real unit starts one stagger step late — Canva does the same.
 *
 * [graphemeLines] gives the line of every grapheme (in [CanvaTextUnitMap.graphemes] order) from
 * the renderer's own layout; null means one line. A paragraph's pseudo item takes the line of the
 * paragraph's first grapheme; an EMPTY paragraph's pseudo item takes the line of the item before
 * it (Canva's `qrf` only starts a line on a visible character, never on a newline).
 */
fun canvaTextUnits(text: String, unit: Int, graphemeLines: IntArray? = null): CanvaTextUnitMap {
    val paragraphs = (text + "\n").split("\n").dropLast(1)
    val graphemes = ArrayList<String>()
    val starts = ArrayList<Int>()
    val blanks = ArrayList<Boolean>()
    val units = ArrayList<Int>()

    var items = 0
    var previousWhitespace = false
    var previousCjk = false
    var previousLine = 0
    var word = 0
    var unitIndex = 0

    fun advance(whitespace: Boolean, cjk: Boolean, line: Int): Int {
        if (items > 0) {
            if (previousWhitespace || previousCjk || previousCjk != cjk) word++
            unitIndex = when (unit) {
                1 -> items
                2 -> word
                3 -> if (previousLine < line) unitIndex + 1 else unitIndex
                else -> 0
            }
        }
        previousWhitespace = whitespace
        previousCjk = cjk
        previousLine = line
        items++
        return unitIndex
    }

    fun lineOf(graphemeIndex: Int): Int = graphemeLines?.getOrNull(graphemeIndex) ?: 0

    var paragraphOffset = 0
    for (paragraph in paragraphs) {
        val bounds = canvaGraphemeBoundaries(paragraph)
        val clusterCount = bounds.size - 1
        val pseudoLine = when {
            clusterCount > 0 -> lineOf(graphemes.size)
            items > 0 -> previousLine
            else -> 0
        }
        advance(whitespace = true, cjk = false, line = pseudoLine)
        for (k in 0 until clusterCount) {
            val grapheme = paragraph.substring(bounds[k], bounds[k + 1])
            val whitespace = grapheme.anyCanvaCodePoint(::isCanvaWhiteSpace)
            val cjk = grapheme.anyCanvaCodePoint(::isCanvaCjk)
            val u = advance(whitespace, cjk, lineOf(graphemes.size))
            graphemes += grapheme
            starts += paragraphOffset + bounds[k]
            blanks += whitespace
            units += u
        }
        paragraphOffset += paragraph.length + 1
    }
    return CanvaTextUnitMap(
        graphemes = graphemes,
        graphemeStarts = starts.toIntArray(),
        graphemeIsBlank = blanks.toBooleanArray(),
        unitOfGrapheme = units.toIntArray(),
        unitCount = unitIndex + 1
    )
}

// ---- Per-unit tween lists -------------------------------------------------------------------------

/**
 * One unit's look at one instant (§8.4): its own alpha, its blur in EMs of the glyph's font size
 * (0.2 at most — read as em, inferred from Canva's 32px whole-element blur, not measured) and its
 * scale about the glyph's own centre.
 */
data class CanvaUnitVisual(val alpha: Float, val blurEm: Float, val scale: Float) {
    /** Drawn exactly like plain text. */
    val isAtRest: Boolean get() = alpha >= 0.999f && blurEm <= 0.0001f && abs(scale - 1f) <= 0.0001f
}

private val CanvaUnitRest = CanvaUnitVisual(alpha = 1f, blurEm = 0f, scale = 1f)

/** True for the four presets Canva animates per unit. */
fun LayerAnimationType.hasCanvaWritingStyles(): Boolean = when (this) {
    LayerAnimationType.FADE,
    LayerAnimationType.BLUR,
    LayerAnimationType.SUCCESSION,
    LayerAnimationType.NEON -> true
    else -> false
}

/**
 * The per-unit schedule of one writing-style slot, resolved once for a text of [unitCount] units
 * and evaluated per frame. Everything but the progress is a key: renderers cache one of these per
 * text and rebuild it only when [matches] says the spec or the unit count moved.
 *
 * * FADE (`Crf`): unit u tweens opacity over 500ms from 125·u — easeOutQuad in, easeInQuad out.
 * * BLUR (`gsf`): opacity + blur .2 over 400ms from 100·u.
 * * SUCCESSION (`ttf`): as BLUR plus scale `.8 − .4·Vd` (`ptf`/`qtf`), and the element scale
 *   `.9 − .3·Vd` over the units' whole span (`rtf`/`stf`).
 * * NEON (`Gsf`): each unit runs Canva's own flicker lists (`Esf` / `Fsf`, 500ms, parity from its
 *   unit index) from an offset that starts at 100 and moves by `lerp(−100, 300, r(u))` at every new
 *   unit, `r(s) = |cos(s)·seed| mod 1` (seed absent → P = 1).
 *
 * `$qf`/`Yqf`/`Zqf` then fit the lists into the slot window [0, durationMs]: the factor is
 * `window / (latest tween end)`, clamped to ≤ 1 unless [fill] (NEON always fits), and every delay
 * and duration is scaled and FLOORED (`Zqf`). Vd = `clamp(intensity − .5, 0, 1)`.
 */
class CanvaUnitSchedule(
    val type: LayerAnimationType,
    val fill: Boolean,
    val intensity: Float,
    val seed: Double?,
    val durationMs: Long,
    val isExiting: Boolean,
    val unitCount: Int
) {
    private val window = durationMs.coerceAtLeast(1L).toDouble()
    private val vd = canvaSliderT(intensity)
    private val count = unitCount.coerceAtLeast(1)

    private val staggerMs = if (type == LayerAnimationType.FADE) 125.0 else 100.0
    private val tweenMs = if (type == LayerAnimationType.FADE) 500.0 else 400.0

    /** `Yqf` + `$qf`: the fit (or fill) factor of the FADE / BLUR / SUCCESSION lists. */
    private val factor: Double = run {
        val latestEnd = (0.0 + staggerMs * (count - 1)) + tweenMs
        val raw = window / latestEnd
        if (fill) raw else min(1.0, raw)
    }
    private val unitDuration = max(1.0, floor(tweenMs * factor))

    private fun unitDelay(unit: Int): Double = max(0.0, floor(0.0 + ((0.0 + staggerMs * unit) - 0.0) * factor))

    private val unitScaleFrom = 0.8 - 0.4 * vd
    private val elementScaleFrom = 0.9 - (0.9 - 0.6) * vd

    /** NEON: every unit's fitted, deduped and sorted list, built once. */
    private val neonLists: Array<List<CanvaTween>> by lazy { buildNeonLists() }

    fun matches(
        type: LayerAnimationType,
        fill: Boolean,
        intensity: Float,
        seed: Double?,
        durationMs: Long,
        isExiting: Boolean,
        unitCount: Int
    ): Boolean = this.type == type && this.fill == fill && this.intensity == intensity && this.seed == seed &&
        this.durationMs == durationMs && this.isExiting == isExiting && this.unitCount == unitCount

    /** Unit [unitIndex]'s look at [rawProgress] (the slot's own clock: p entering, u exiting). */
    fun visual(unitIndex: Int, rawProgress: Float): CanvaUnitVisual {
        val tau = canvaExactProgress(rawProgress) * window
        val unit = unitIndex.coerceIn(0, count - 1)
        return when (type) {
            LayerAnimationType.FADE -> {
                val tween = unitTween(unit, from = 0.0, to = 1.0)
                CanvaUnitVisual(alpha = tween.valueAt(tau).toFloat(), blurEm = 0f, scale = 1f)
            }
            LayerAnimationType.BLUR,
            LayerAnimationType.SUCCESSION -> {
                val alpha = unitTween(unit, from = 0.0, to = 1.0).valueAt(tau)
                val blur = unitTween(unit, from = 0.2, to = 0.0).valueAt(tau)
                val scale = if (type == LayerAnimationType.SUCCESSION) {
                    unitTween(unit, from = unitScaleFrom, to = 1.0).valueAt(tau)
                } else {
                    1.0
                }
                CanvaUnitVisual(alpha = alpha.toFloat(), blurEm = blur.toFloat(), scale = scale.toFloat())
            }
            LayerAnimationType.NEON -> CanvaUnitVisual(
                alpha = canvaLatestTweenValue(tau, neonLists[unit], fallback = if (isExiting) 1.0 else 0.0)
                    .toFloat().coerceIn(0f, 1f),
                blurEm = 0f,
                scale = 1f
            )
            else -> CanvaUnitRest
        }
    }

    /**
     * SUCCESSION's element scale (`rtf` / `stf`) — every other type is 1: `.9 − .3·Vd` → 1 on
     * easeOutQuad (out: 1 → it on easeInQuad) over [first unit's delay, last unit's delay + its
     * duration], evaluated like any tween.
     */
    fun elementScale(rawProgress: Float): Float {
        if (type != LayerAnimationType.SUCCESSION) return 1f
        val tau = canvaExactProgress(rawProgress) * window
        val firstDelay = unitDelay(0)
        val lastDelay = unitDelay(count - 1)
        val span = lastDelay - firstDelay + unitDuration
        val tween = if (isExiting) {
            CanvaTween(firstDelay, span, 1.0, elementScaleFrom, CANVA_EASE_IN_QUAD)
        } else {
            CanvaTween(firstDelay, span, elementScaleFrom, 1.0, CANVA_EASE_OUT_QUAD)
        }
        return tween.valueAt(tau).toFloat()
    }

    /** A FADE / BLUR / SUCCESSION unit tween, entering ([from] → [to]) or exiting ([to] → [from]). */
    private fun unitTween(unit: Int, from: Double, to: Double): CanvaTween = if (isExiting) {
        CanvaTween(unitDelay(unit), unitDuration, to, from, CANVA_EASE_IN_QUAD)
    } else {
        CanvaTween(unitDelay(unit), unitDuration, from, to, CANVA_EASE_OUT_QUAD)
    }

    private fun buildNeonLists(): Array<List<CanvaTween>> {
        val random = seed ?: 1.0
        val offsets = DoubleArray(count)
        var offset = 100.0
        offsets[0] = offset
        for (m in 1 until count) {
            offset += canvaLerpD(-100.0, 300.0, abs(cos(m.toDouble()) * random) % 1.0)
            offsets[m] = offset
        }
        val raw = Array(count) { unit ->
            val delay = max(0.0, 0.0 + offsets[unit])
            if (isExiting) {
                canvaNeonUnitOutro(delay, duration = 500.0, vd = vd, xh = unit)
            } else {
                canvaNeonUnitIntro(delay, duration = 500.0, vd = vd, xh = unit)
            }
        }
        var latestEnd = 0.0
        raw.forEach { list -> list.forEach { tween -> latestEnd = max(latestEnd, tween.delay + tween.duration) } }
        // Gsf calls $qf with no modes: NEON always FITS, whatever the stored duration.
        val neonFactor = min(1.0, window / (latestEnd - 0.0))
        return Array(count) { unit ->
            raw[unit].map { it.fitted(neonFactor) }.canvaDeduped().canvaSortedForEvaluation()
        }
    }
}

/** Canva's `Esf` — NEON's intro flicker for one unit (LINEAR opacity tweens, hold rule applies). */
internal fun canvaNeonUnitIntro(delay: Double, duration: Double, vd: Double, xh: Int): List<CanvaTween> {
    val c = duration / canvaLerpD(10.0, 26.0, vd)
    val steps = floor(canvaLerpD(1.0, 4.0, vd)).toInt()
    val even = xh % 2 == 0
    fun tween(from: Double, to: Double, at: Double, length: Double) = CanvaTween(at, length, from, to, CANVA_EASE_LINEAR)
    var f = delay
    val list = ArrayList<CanvaTween>()
    for (h in 0 until steps) {
        if (h % 2 == 0) {
            list += tween(0.0, 1.0, f, c * 3)
            list += if (even) tween(1.0, 0.0, f + c * 4, c) else tween(0.0, 0.0, f + c * 4, c)
            f += c * 5
        } else {
            list += if (even) tween(1.0, 1.0, f + c * 1, c) else tween(0.75, 0.75, f + c * 1, c)
            list += tween(0.0, 0.0, f + c * 3, c)
            f += c * 4
        }
    }
    list += if (!even) tween(0.0, 1.0, f + c * 5, c * 4) else tween(0.0, 1.0, f + c * 4, c * 3)
    return list
}

/** Canva's `Fsf` — NEON's outro flicker for one unit. */
internal fun canvaNeonUnitOutro(delay: Double, duration: Double, vd: Double, xh: Int): List<CanvaTween> {
    fun tween(from: Double, to: Double, at: Double, length: Double) = CanvaTween(at, length, from, to, CANVA_EASE_LINEAR)
    if (duration <= 0.0) return listOf(tween(1.0, 0.0, delay, 0.0))
    val d = duration / canvaLerpD(4.0, 8.0, vd)
    return if (xh % 2 == 0) {
        listOf(
            tween(1.0, 1.0, delay + 1, 1.0),
            tween(0.0, 0.0, delay + 1 + d * 1.1, max(0.0, d * 0.9 - 1)),
            tween(0.5, 0.5, delay + d * 3, d),
            tween(0.0, 0.0, delay + d * 5, d)
        )
    } else {
        listOf(
            tween(1.0, 0.5, delay + d, d * 2),
            tween(0.5, 0.0, delay + d * 4, d * 0.1)
        )
    }
}

// ---- The pure entry points the renderers and the web golden share -------------------------------

/**
 * Unit [unitIndex] of [unitCount]'s look for writing style [unit] of a [type] slot at [rawProgress]
 * — p while entering, u (0 → 1 over the outro) while exiting. Neutral for any other type/unit.
 */
fun canvaUnitVisual(
    type: LayerAnimationType,
    unit: Int,
    fill: Boolean,
    intensity: Float,
    seed: Double?,
    durationMs: Long,
    isExiting: Boolean,
    rawProgress: Float,
    unitIndex: Int,
    unitCount: Int
): CanvaUnitVisual {
    if (unit !in 1..3 || !type.hasCanvaWritingStyles()) return CanvaUnitRest
    return CanvaUnitSchedule(type, fill, intensity, seed, durationMs, isExiting, unitCount)
        .visual(unitIndex, rawProgress)
}

/** SUCCESSION's element scale for the same inputs (1 for every other type). */
fun canvaUnitElementScale(
    type: LayerAnimationType,
    unit: Int,
    fill: Boolean,
    intensity: Float,
    seed: Double?,
    durationMs: Long,
    isExiting: Boolean,
    rawProgress: Float,
    unitCount: Int
): Float {
    if (unit !in 1..3 || !type.hasCanvaWritingStyles()) return 1f
    return CanvaUnitSchedule(type, fill, intensity, seed, durationMs, isExiting, unitCount)
        .elementScale(rawProgress)
}

// ---- Renderer plumbing ----------------------------------------------------------------------------

/** The UTF-16 start of every real grapheme of [text], in [canvaTextUnits] order. */
fun canvaGraphemeStarts(text: String): IntArray {
    val starts = ArrayList<Int>(text.length)
    var paragraphOffset = 0
    for (paragraph in (text + "\n").split("\n").dropLast(1)) {
        val bounds = canvaGraphemeBoundaries(paragraph)
        for (k in 0 until bounds.size - 1) starts += paragraphOffset + bounds[k]
        paragraphOffset += paragraph.length + 1
    }
    return starts.toIntArray()
}

/**
 * The unit map and schedule of ONE text as a renderer draws it, cached across frames: the map is
 * rebuilt only when the text, the writing style or (line mode only) the layout changes, the
 * schedule only when the spec's keys or the unit count do. Single-threaded, like the renderers.
 *
 * [lineOfOffset] maps a UTF-16 offset to its line in the renderer's OWN layout — line units come
 * from what is drawn, never from an estimate — and is only consulted for writing style 3.
 */
class CanvaUnitTextCache {
    private var text: String? = null
    private var unit = 0
    private var layoutKey: Any? = null
    private var map: CanvaTextUnitMap? = null
    private var schedule: CanvaUnitSchedule? = null

    fun unitMap(text: String, unit: Int, layoutKey: Any?, lineOfOffset: ((Int) -> Int)?): CanvaTextUnitMap {
        val key = if (unit == 3) layoutKey else null
        val cached = map
        if (cached != null && this.text == text && this.unit == unit && this.layoutKey === key) return cached
        val lines = if (unit == 3 && lineOfOffset != null) {
            canvaGraphemeStarts(text).let { starts -> IntArray(starts.size) { lineOfOffset(starts[it]) } }
        } else {
            null
        }
        return canvaTextUnits(text, unit, lines).also {
            this.text = text
            this.unit = unit
            this.layoutKey = key
            map = it
        }
    }

    fun schedule(motion: GlyphMotionSpec, unitCount: Int): CanvaUnitSchedule? =
        motion.canvaSchedule(unitCount, reuse = schedule)?.also { schedule = it }
}
